import type { Cart } from './cart.js';
import { charge } from './payments.js';

export async function pay(cart: Cart) {
    try {
        // eslint-disable-next-line
        charge(cart.total);
    } catch {}
}

import type { Cart } from './cart.js';
import { charge } from './payments.js';

export async function pay(cart: Cart) {
    await charge(cart.total);
}
